const signsInWithoutACallbackPort = useDeviceCode || useClientCredentials;
const redirectToAuthorization = authProvider.redirectToAuthorization.bind(authProvider);
authProvider.redirectToAuthorization = async (authorizationUrl) => {
  if (!signsInWithoutACallbackPort) {
    const { skipBrowserAuth } = await authInitializer();
    if (skipBrowserAuth) {
      await authProvider.invalidateCredentials("verifier");
      return;
    }
  }
  return redirectToAuthorization(authorizationUrl);
};
